from fastapi import FastAPI, APIRouter, FastAPIError
import pytest

def test_include_router_into_itself():
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as e:
        assert str(e) == "You cannot include a router into itself"
        return
    except Exception as e:
        pytest.fail(f"Unexpected exception type: {type(e).__name__}: {e}")

    pytest.fail("Expected FastAPIError was not raised")

if __name__ == "__main__":
    try:
        test_include_router_into_itself()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

